import { EsiClient } from '../../../../src/EsiClient';
import { EsiError } from '../../../../src/core/util/error';
import { TestDataFactory } from '../../../../src/testing/TestDataFactory';

const feature = loadFeature('tests/bdd/features/core/skills.feature');

defineFeature(feature, (test) => {
  let client: EsiClient;

  beforeEach(() => {
    client = new EsiClient({
      clientId: 'test-client',
      baseUrl: 'https://esi.evetech.net',
      accessToken: 'mock-access-token',
      timeout: 5000,
    });
  });

  test('WHEN getCharacterSkills is called, the client shall return the skills list with total SP', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const expectedSkills = TestDataFactory.createCharacterSkills();

    given('the ESI skills endpoint is available for a character', () => {
      jest
        .spyOn(client.skills, 'getCharacterSkills')
        .mockResolvedValue(expectedSkills);
    });

    when('getCharacterSkills is called with the character ID', async () => {
      result = await client.skills.getCharacterSkills(characterId);
    });

    then('the client shall return a skills object with skills array and total_sp', () => {
      expect(result).toBeDefined();
      expect(result.skills).toHaveLength(2);
      expect(result.total_sp).toBe(384000);
      expect(result.skills[0].skill_id).toBe(3300);
      expect(result.skills[0].trained_skill_level).toBe(5);
    });
  });

  test('WHEN getCharacterSkills is called for a veteran character, the client shall return a large skill set', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const manySkills = {
      skills: [
        TestDataFactory.createCharacterSkill({
          skill_id: 3300,
          skillpoints_in_skill: 1280000,
          trained_skill_level: 5,
        }),
        TestDataFactory.createCharacterSkill({
          skill_id: 3301,
          skillpoints_in_skill: 1280000,
          trained_skill_level: 5,
        }),
        TestDataFactory.createCharacterSkill({
          skill_id: 3302,
          skillpoints_in_skill: 512000,
          trained_skill_level: 5,
        }),
        TestDataFactory.createCharacterSkill({
          skill_id: 3303,
          skillpoints_in_skill: 256000,
          trained_skill_level: 4,
        }),
        TestDataFactory.createCharacterSkill({
          skill_id: 3304,
          skillpoints_in_skill: 768000,
          trained_skill_level: 5,
        }),
      ],
      total_sp: 80000000,
      unallocated_sp: 500000,
    };

    given('the ESI skills endpoint is available for a veteran character with high SP', () => {
      jest
        .spyOn(client.skills, 'getCharacterSkills')
        .mockResolvedValue(manySkills);
    });

    when('getCharacterSkills is called with the veteran character ID', async () => {
      result = await client.skills.getCharacterSkills(characterId);
    });

    then('the client shall return a skills object with many skills and high total_sp', () => {
      expect(result).toBeDefined();
      expect(result.skills).toHaveLength(5);
      expect(result.total_sp).toBe(80000000);
      expect(result.unallocated_sp).toBe(500000);
    });
  });

  test('WHEN getCharacterSkillQueue is called, the client shall return an ordered training queue', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const expectedQueue = [
      {
        skill_id: 3300,
        finished_level: 5,
        queue_position: 0,
        start_date: '2024-01-15T12:00:00Z',
        finish_date: '2024-01-20T12:00:00Z',
      },
      {
        skill_id: 3301,
        finished_level: 4,
        queue_position: 1,
        start_date: '2024-01-20T12:00:00Z',
        finish_date: '2024-02-01T12:00:00Z',
      },
      {
        skill_id: 3302,
        finished_level: 3,
        queue_position: 2,
        start_date: '2024-02-01T12:00:00Z',
        finish_date: '2024-02-05T12:00:00Z',
      },
    ];

    given('the ESI skill queue endpoint is available for a character with skills in training', () => {
      jest
        .spyOn(client.skills, 'getCharacterSkillQueue')
        .mockResolvedValue(expectedQueue as any);
    });

    when('getCharacterSkillQueue is called with the character ID', async () => {
      result = await client.skills.getCharacterSkillQueue(characterId);
    });

    then('the client shall return an ordered array of queued skills with queue positions', () => {
      expect(result).toBeDefined();
      expect(result).toHaveLength(3);
      expect(result[0].queue_position).toBe(0);
      expect(result[1].queue_position).toBe(1);
      expect(result[2].queue_position).toBe(2);
      expect(result[0].skill_id).toBe(3300);
      expect(result[0].finished_level).toBe(5);
    });
  });

  test('WHEN getCharacterSkillQueue returns no results, the client shall return an empty array', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;

    given('the ESI skill queue endpoint is available for a character with no skills in training', () => {
      jest.spyOn(client.skills, 'getCharacterSkillQueue').mockResolvedValue([]);
    });

    when('getCharacterSkillQueue is called with the idle character ID', async () => {
      result = await client.skills.getCharacterSkillQueue(characterId);
    });

    then('the client shall return an empty array', () => {
      expect(Array.isArray(result)).toBe(true);
      expect(result).toHaveLength(0);
    });
  });

  test('WHEN getCharacterAttributes is called, the client shall return all five attributes and remap info', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const expectedAttributes = TestDataFactory.createCharacterAttributes();

    given('the ESI attributes endpoint is available for a character', () => {
      jest
        .spyOn(client.skills, 'getCharacterAttributes')
        .mockResolvedValue(expectedAttributes);
    });

    when('getCharacterAttributes is called with the character ID', async () => {
      result = await client.skills.getCharacterAttributes(characterId);
    });

    then('the client shall return an object with all five neural attributes and bonus remaps', () => {
      expect(result).toBeDefined();
      expect(result.intelligence).toBe(24);
      expect(result.memory).toBe(21);
      expect(result.perception).toBe(23);
      expect(result.willpower).toBe(22);
      expect(result.charisma).toBe(20);
      expect(result.bonus_remaps).toBe(2);
    });
  });

  test('WHILE a character has a custom remap, getCharacterAttributes shall return the remapped values', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const perceptionFocused = TestDataFactory.createCharacterAttributes({
      perception: 32,
      willpower: 27,
      intelligence: 17,
      memory: 17,
      charisma: 17,
      bonus_remaps: 0,
    });

    given('the character has a perception-focused neural remap applied', () => {
      jest
        .spyOn(client.skills, 'getCharacterAttributes')
        .mockResolvedValue(perceptionFocused);
    });

    when('getCharacterAttributes is called for the remapped character', async () => {
      result = await client.skills.getCharacterAttributes(characterId);
    });

    then('the client shall return elevated perception and adjusted attribute values', () => {
      expect(result.perception).toBe(32);
      expect(result.willpower).toBe(27);
      expect(result.bonus_remaps).toBe(0);
    });
  });

  test('IF authorization token is invalid or expired, THEN the client shall throw an EsiError with status 403', ({ given, when, then }) => {
    let caughtError: any;
    const characterId = 90000001;

    given('the authorization token is invalid or expired', () => {
      const error = TestDataFactory.createError(403);
      jest.spyOn(client.skills, 'getCharacterSkills').mockRejectedValue(error);
    });

    when('getCharacterSkills is called without valid authorization', async () => {
      try {
        await client.skills.getCharacterSkills(characterId);
      } catch (e) {
        caughtError = e;
      }
    });

    then('the client shall throw an EsiError with status 403', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('WHEN skills, queue, and attributes are fetched concurrently, the client shall return all three successfully', ({
    given,
    when,
    then,
  }) => {
    let skills: any;
    let queue: any;
    let attributes: any;
    const characterId = 90000001;
    const skillsData = TestDataFactory.createCharacterSkills();
    const queueData = [
      {
        skill_id: 3305,
        finished_level: 4,
        queue_position: 0,
        start_date: '2024-03-01T00:00:00Z',
        finish_date: '2024-03-10T00:00:00Z',
      },
    ];
    const attributesData = TestDataFactory.createCharacterAttributes();

    given('the ESI skills, queue, and attributes endpoints are all available for a character', () => {
      jest
        .spyOn(client.skills, 'getCharacterSkills')
        .mockResolvedValue(skillsData);
      jest
        .spyOn(client.skills, 'getCharacterSkillQueue')
        .mockResolvedValue(queueData as any);
      jest
        .spyOn(client.skills, 'getCharacterAttributes')
        .mockResolvedValue(attributesData);
    });

    when('getCharacterSkills, getCharacterSkillQueue, and getCharacterAttributes are called concurrently', async () => {
      [skills, queue, attributes] = await Promise.all([
        client.skills.getCharacterSkills(characterId),
        client.skills.getCharacterSkillQueue(characterId),
        client.skills.getCharacterAttributes(characterId),
      ]);
    });

    then('the client shall return valid data from all three endpoints', () => {
      expect(skills.skills).toHaveLength(2);
      expect(skills.total_sp).toBe(384000);
      expect(queue).toHaveLength(1);
      expect(queue[0].queue_position).toBe(0);
      expect(attributes.intelligence).toBe(24);
      expect(attributes.perception).toBe(23);
    });
  });
});
